import { createCourse, files, test, type CourseSpec, type LessonSpec, type QuestionSpec, type StageSpec } from "@/lib/course-factory";
import type { CourseBundle, CourseId, ProjectChoice } from "@/lib/course";

type PathProfile = {
  id: CourseId;
  title: string;
  ageRange: string;
  ages: number[];
  estimatedHours: string;
  audience: string;
  advanced: boolean;
  projectChoices: ProjectChoice[];
};

type LessonInput = Omit<LessonSpec, "minutes" | "notes" | "exampleTitle" | "exampleExplanation"> & {
  minutes?: number;
  concept: string;
  method: string;
  exampleTitle?: string;
  exampleExplanation?: string;
};

const q = (prompt: string, correct: string, wrongOne: string, wrongTwo: string, explanation: string): QuestionSpec => [prompt, correct, wrongOne, wrongTwo, explanation];

function lesson(input: LessonInput, audience: string): LessonSpec {
  return {
    ...input,
    minutes: input.minutes || 15,
    notes: [
      `${input.concept} This matters because ${audience} should be able to explain what the code is doing, not only copy a finished answer. Connect each new symbol or keyword to the visible result it creates in the browser.`,
      `${input.method} Read the worked example from top to bottom before editing. Predict what will appear, change one small part, run the page and compare the result with your prediction. If the result is different, inspect the exact line you changed before adding more code.`,
    ],
    exampleTitle: input.exampleTitle || "A complete working pattern",
    exampleExplanation: input.exampleExplanation || `The example shows the smallest complete pattern needed for this task. Every named part has one job, so it can be tested separately before it becomes part of the larger website.`,
  };
}

const projectOpeningHtml = `<h1>{{TITLE}}</h1>
<p>{{INTRO}}</p>
<!-- Build the page regions around this starting content. -->`;

const projectStructureHtml = `<header>
  <h1>{{TITLE}}</h1>
  <nav><a href="#topics">Topics</a> <a href="#contact">Contact</a></nav>
</header>
<main>
  <p>{{INTRO}}</p>
  <section id="topics" class="cards">
    <article class="card"><h2>{{ITEM1}}</h2><p>Add useful information here.</p></article>
    <article class="card"><h2>{{ITEM2}}</h2><p>Add useful information here.</p></article>
    <article class="card"><h2>{{ITEM3}}</h2><p>Add useful information here.</p></article>
  </section>
</main>
<footer><p>Project in progress.</p></footer>`;

const projectFormHtml = projectStructureHtml.replace(
  "</main>",
  `  <form id="contact">
    <label for="visitor-name">Your name</label>
    <input id="visitor-name" name="visitor-name" type="text" required>
    <button type="submit">Send</button>
  </form>
  <p id="status" role="status">Ready</p>
</main>`,
);

const projectDataHtml = projectFormHtml.replace(
  "</main>",
  `  <ul id="topic-list"></ul>
</main>`,
);

const projectVisualCss = `:root { --ink: #111936; --accent: #5a2676; --paper: #f7f3ea; --highlight: #ee9d2b; }
* { box-sizing: border-box; }
body { margin: 0; padding: 2rem; background: var(--paper); color: var(--ink); font-family: Arial, sans-serif; line-height: 1.6; }
.card { padding: 1rem; border: 2px solid var(--ink); border-radius: 12px; }`;

const projectResponsiveCss = `${projectVisualCss}
nav { display: flex; flex-wrap: wrap; gap: 1rem; }
.cards { display: grid; grid-template-columns: 1fr; gap: 1rem; }
@media (min-width: 700px) {
  .cards { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}`;

const projectBehaviourJavaScript = `const statusText = document.querySelector("#status");

function showAvailability(count) {
  if (count > 0) {
    statusText.textContent = "Information available";
  } else {
    statusText.textContent = "No information available";
  }
}

showAvailability(3);`;

const projectDataJavaScript = `${projectBehaviourJavaScript}

const topics = [
  { title: "{{ITEM1}}" },
  { title: "{{ITEM2}}" },
  { title: "{{ITEM3}}" },
];
const topicList = document.querySelector("#topic-list");

topics.forEach(function (topic) {
  const item = document.createElement("li");
  item.textContent = topic.title;
  topicList.append(item);
});`;

const projectSavedStateJavaScript = `${projectDataJavaScript}

const form = document.querySelector("#contact");
const visitorNameInput = document.querySelector("#visitor-name");
const savedName = localStorage.getItem("project-visitor-name");

if (savedName) {
  visitorNameInput.value = savedName;
  statusText.textContent = "Saved name restored";
}

form.addEventListener("submit", function (event) {
  event.preventDefault();
  const visitorName = visitorNameInput.value.trim();
  if (visitorName === "") {
    statusText.textContent = "Please enter a name";
    return;
  }
  localStorage.setItem("project-visitor-name", visitorName);
  statusText.textContent = "Saved";
});`;

function projectStarterFiles(stage: number) {
  if (stage === 1) return files(projectOpeningHtml);
  if (stage === 2) return files(projectStructureHtml);
  if (stage === 3) return files(projectFormHtml);
  if (stage === 4) return files(projectFormHtml, projectVisualCss);
  if (stage === 5) return files(projectFormHtml, projectResponsiveCss);
  if (stage === 6) return files(projectFormHtml, projectResponsiveCss, projectBehaviourJavaScript);
  if (stage === 7) return files(projectDataHtml, projectResponsiveCss, projectDataJavaScript);
  return files(projectDataHtml, projectResponsiveCss, projectSavedStateJavaScript);
}

