function stageOne(audience: string, advanced: boolean): StageSpec {
  const lessons: [LessonSpec, LessonSpec, LessonSpec, LessonSpec] = [
    lesson({ id: "landmarks", title: "Plan meaningful page regions", language: "HTML", objective: "Use semantic elements to describe the large parts of a page.", concept: "Semantic HTML names the job of content. Header, nav, main, section, article and footer make the outline understandable before any styling is added.", method: "Sketch the reading order first. Use one main region and reserve article for content that could stand on its own.", keyTerms: ["semantic HTML", "landmark", "article"], exampleCode: `<header><nav>...</nav></header>\n<main><section><article>...</article></section></main>\n<footer>...</footer>`, task: "Replace the generic div elements with header, nav, main, section and footer.", starterFiles: files(`<div><h1>Directory</h1><div><a href="#list">List</a></div></div>\n<div id="list"><h2>Services</h2><p>Useful details.</p></div>\n<div>Updated today</div>`), editableFiles: ["html"], tests: [test("html", "Uses a header", "<header[\\s>]"), test("html", "Uses navigation", "<nav[\\s>]"), test("html", "Uses main", "<main[\\s>]"), test("html", "Uses a section", "<section[\\s>]"), test("html", "Uses a footer", "<footer[\\s>]")], hints: ["Identify the introduction, navigation, main information and ending.", "Change matching opening and closing div tags one pair at a time.", "Use header around h1 and nav, main around section, then footer for the update."], question: q("What does a semantic element communicate?", "The job of its content", "Its download speed", "A secret value", "Semantic names create a meaningful page outline.") }, audience),
    lesson({ id: "headings", title: "Build a heading hierarchy", language: "HTML", objective: "Organise a page with one h1 and logical section headings.", concept: "Headings form an outline. The h1 identifies the page and lower heading levels introduce sections in a logical order.", method: "Read only the headings in sequence. If that short outline explains the page, the hierarchy is doing its job.", keyTerms: ["heading hierarchy", "h1", "section heading"], exampleCode: `<h1>Study Planner</h1>\n<section><h2>This week</h2><h3>Mathematics</h3></section>`, task: "Add one h1, two h2 section headings and one h3 inside the second section.", starterFiles: files(`<main>\n  <p>Learning Library</p>\n  <section><p>New resources</p></section>\n  <section><p>Popular topics</p><p>Web development</p></section>\n</main>`), editableFiles: ["html"], tests: [test("html", "Has one main heading", "<h1[\\s>][\\s\\S]*</h1>"), test("html", "Has two section headings", "(?:<h2[\\s>][\\s\\S]*</h2>){2}"), test("html", "Has a nested heading", "<h3[\\s>][\\s\\S]*</h3>")], hints: ["Turn the page name into h1.", "Turn each section name into h2.", "Use h3 only for the topic that belongs inside the second section."], question: q("What should the h1 identify?", "The whole page", "Every small card", "The stylesheet", "The h1 gives the page its main heading.") }, audience),
    lesson({ id: "links", title: "Write useful navigation links", language: "HTML", objective: "Create descriptive links that reach page sections.", concept: "A link needs a destination and words that make sense outside the surrounding sentence. Fragment links use an element id as a destination on the same page.", method: "Give the destination a unique id, then use # followed by that id in href. Read the link text alone and make sure it names the destination.", keyTerms: ["anchor", "href", "fragment identifier"], exampleCode: `<a href="#services">View services</a>\n<section id="services">...</section>`, task: "Create links to #about and #contact using descriptive text, then add matching section ids.", starterFiles: files(`<nav>About Contact</nav>\n<main><section><h2>About us</h2></section><section><h2>Contact us</h2></section></main>`), editableFiles: ["html"], tests: [test("html", "Links to about", "<a[^>]+href=[\"']#about[\"'][^>]*>[^<]+</a>"), test("html", "Links to contact", "<a[^>]+href=[\"']#contact[\"'][^>]*>[^<]+</a>"), test("html", "Has about destination", "id=[\"']about[\"']"), test("html", "Has contact destination", "id=[\"']contact[\"']")], hints: ["Wrap each navigation phrase in an a element.", "The href includes # but the id value does not.", "Use href=#about with id=about, then repeat the pattern for contact."], question: q("What must match for a page fragment link?", "The href after # and the destination id", "The font sizes", "Two image sources", "Matching values let the browser find the section.") }, audience),
    lesson({ id: "metadata", title: advanced ? "Add useful document metadata" : "Describe images clearly", language: "HTML", objective: advanced ? "Add a title and viewport information for the document." : "Write alternative text that communicates an image's purpose.", concept: advanced ? "Document metadata helps browsers name and display the page correctly. The title identifies the tab and the viewport setting lets responsive layouts use the device width." : "Alternative text provides the image information when the picture is unavailable or cannot be seen. The wording should communicate purpose, not begin with a redundant phrase.", method: advanced ? "Place metadata inside head, keep the title specific and use the standard width=device-width viewport value." : "Ask what information would be missing if the picture disappeared, then write only that useful information in alt.", keyTerms: advanced ? ["metadata", "title", "viewport"] : ["image", "alternative text", "src"], exampleCode: advanced ? `<head>\n  <title>Community Opportunity Directory</title>\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n</head>` : `<img src="workshop.jpg" alt="Three learners testing a webpage together">`, task: advanced ? "Add a specific title and the standard responsive viewport meta element." : "Add a useful alt description to the image.", starterFiles: advanced ? files(`<!doctype html><html lang="en"><head></head><body><h1>Opportunity Directory</h1></body></html>`) : files(`<h1>Photography guide</h1>\n<img src="camera.jpg">`), editableFiles: ["html"], tests: advanced ? [test("html", "Has a specific title", "<title>[^<]{5,}</title>"), test("html", "Has viewport metadata", "<meta[^>]+name=[\"']viewport[\"'][^>]+width=device-width")] : [test("html", "Image has useful alt text", "<img[^>]+alt=[\"'][^\"']{8,}[\"']")], hints: advanced ? ["Metadata belongs inside head.", "Add title first, then a meta element named viewport.", "Use content=width=device-width, initial-scale=1 for the viewport."] : ["Describe the useful information, not the file name.", "Place alt inside the img opening tag.", "For example, alt=Camera beside an open notebook."], question: advanced ? q("Why include viewport metadata?", "It lets responsive CSS use the device width correctly", "It saves form data", "It creates a footer", "The viewport setting is essential for predictable mobile layout.") : q("What should alt text communicate?", "The image information or purpose", "The CSS colour", "The browser history", "Alternative text replaces the useful meaning of the image.") }, audience),
  ];
  return { id: "structure", title: "Meaningful HTML structure", description: "Turn content into a page with a clear outline and useful navigation.", outcome: "A semantic project foundation that works without CSS.", lessons, project: projectLesson(1, audience, advanced), quizQuestion: q("Which element contains the page's primary content?", "main", "style", "title", "The main element holds the central page content.") };
}

function stageTwo(audience: string, advanced: boolean): StageSpec {
  const lessons: [LessonSpec, LessonSpec, LessonSpec, LessonSpec] = [
    lesson({ id: "labels", title: "Connect labels and controls", language: "HTML", objective: "Create a programmatic connection between visible instructions and inputs.", concept: "A form control needs a visible label. Matching the label for value with the control id helps mouse, touch and assistive-technology users understand and activate the field.", method: "Choose a unique short id, write it once on the input and repeat it exactly in the label for attribute.", keyTerms: ["label", "id", "form control"], exampleCode: `<label for="topic">Topic</label>\n<input id="topic" type="text">`, task: "Connect the existing name and email labels to their inputs.", starterFiles: files(`<form>\n<label>Name</label><input type="text">\n<label>Email</label><input type="email">\n</form>`), editableFiles: ["html"], tests: [test("html", "Name label is connected", "<label[^>]+for=[\"']name[\"'][^>]*>[\\s\\S]*<input[^>]+id=[\"']name[\"']"), test("html", "Email label is connected", "<label[^>]+for=[\"']email[\"'][^>]*>[\\s\\S]*<input[^>]+id=[\"']email[\"']")], hints: ["Give each input a different id.", "Add for to each label.", "Use for=name with id=name, then for=email with id=email."], question: q("Why must for and id match?", "They tell the browser which label belongs to which control", "They choose a CSS colour", "They download the form", "The match creates an accessible label connection.") }, audience),
    lesson({ id: "types", title: "Choose the correct input type", language: "HTML", objective: "Use browser features suited to the information being entered.", concept: "Input type tells the browser what kind of value a field expects. It can provide a suitable phone keyboard and basic validation, but clear labels and application checks are still required.", method: "Choose the narrowest appropriate type, such as email, number or date, and never use a type simply because it changes appearance.", keyTerms: ["input type", "email input", "browser validation"], exampleCode: `<label for="date">Preferred date</label>\n<input id="date" type="date">`, task: "Set suitable email and number input types and add sensible minimum and maximum values to the number.", starterFiles: files(`<label for="email">Email</label><input id="email">\n<label for="places">Places</label><input id="places">`), editableFiles: ["html"], tests: [test("html", "Uses an email input", "<input[^>]+type=[\"']email[\"']"), test("html", "Uses a number input", "<input[^>]+type=[\"']number[\"']"), test("html", "Number has a minimum", "<input[^>]+min=[\"']?1"), test("html", "Number has a maximum", "<input[^>]+max=")], hints: ["Set the first type to email.", "Set the second type to number.", "Add min=1 and a reasonable max to the number input."], question: q("What does input type tell the browser?", "What kind of value the control expects", "Which CSS file to open", "Which heading is largest", "A suitable type supports entry and basic validation.") }, audience),
    lesson({ id: "groups", title: "Group related choices", language: "HTML", objective: "Use fieldset and legend for a related set of controls.", concept: "A fieldset groups controls that share one question. Its legend gives the whole group a name that remains available to keyboard and assistive-technology users.", method: "Place the legend first inside fieldset, then give each radio or checkbox its own visible label.", keyTerms: ["fieldset", "legend", "radio group"], exampleCode: `<fieldset><legend>Preferred session</legend>\n<label><input type="radio" name="session" value="morning"> Morning</label>\n</fieldset>`, task: "Wrap the three contact choices in a fieldset, add a legend and give them one shared name.", starterFiles: files(`<p>Contact method</p>\n<label><input type="radio"> Email</label>\n<label><input type="radio"> Phone</label>\n<label><input type="radio"> Message</label>`), editableFiles: ["html"], tests: [test("html", "Uses a fieldset", "<fieldset[\\s>]"), test("html", "Has a legend", "<legend[\\s>][^<]+</legend>"), test("html", "Radios share a name", "(?:type=[\"']radio[\"'][^>]+name=[\"']contact[\"']|name=[\"']contact[\"'][^>]+type=[\"']radio[\"'])")], hints: ["Add fieldset around the whole question.", "Move the question text into legend.", "Give every radio name=contact while keeping different values."], question: q("What does legend label?", "The complete group of related controls", "Only the submit button", "The stylesheet", "Legend explains the shared question for a fieldset.") }, audience),
    lesson({ id: "messages", title: advanced ? "Design validation and status messages" : "Add clear form instructions", language: "HTML", objective: "Help a visitor understand requirements and results.", concept: "A useful form explains requirements before submission and reports the result afterwards. A status region lets changing feedback be announced without moving focus unexpectedly.", method: "Place brief instructions near the field, connect extra help with aria-describedby when useful and use role=status for non-urgent results.", keyTerms: ["validation", "aria-describedby", "status message"], exampleCode: `<p id="email-help">Use an address you can open.</p>\n<input id="email" type="email" aria-describedby="email-help">\n<p id="result" role="status"></p>`, task: "Add help text, connect it to the email input and create an empty status paragraph for submission feedback.", starterFiles: files(`<form><label for="email">Email</label><input id="email" type="email"><button>Send</button></form>`), editableFiles: ["html"], tests: [test("html", "Has help text", "id=[\"']email-help[\"']"), test("html", "Input references help", "aria-describedby=[\"']email-help[\"']"), test("html", "Has a status region", "role=[\"']status[\"']")], hints: ["Add a short paragraph with id=email-help.", "Reference that id from the input.", "After the form, add a paragraph with id=result and role=status."], question: q("Why use a status region?", "It communicates changing feedback without forcing focus to move", "It stores a password", "It creates a media query", "Status regions make dynamic results available to more users.") }, audience),
  ];
  return { id: "forms", title: "Accessible forms", description: "Collect only useful information with connected labels and clear feedback.", outcome: "A form that works with touch, keyboard and assistive technology.", lessons, project: projectLesson(2, audience, advanced), quizQuestion: q("What should a form request?", "Only information needed for its stated purpose", "Every detail about the visitor", "A secret password for practice", "Collecting less data improves clarity and privacy.") };
}

function stageThree(audience: string, advanced: boolean): StageSpec {
  const items: Array<LessonInput> = [
    { id: "selectors", title: "Target elements with selectors", language: "CSS", objective: "Choose elements by type and reusable class.", concept: "A selector chooses which HTML receives a rule. Type selectors suit broad defaults, while class selectors create reusable component styles without depending on one element's position.", method: "Use the least specific selector that expresses the design job. Confirm that it affects the intended elements and no unrelated content.", keyTerms: ["selector", "class selector", "specificity"], exampleCode: `body { line-height: 1.6; }\n.card { padding: 1rem; }`, task: "Style every paragraph with readable line height and every .card with padding and a border.", starterFiles: files(`<p>Introduction</p><article class="card"><p>Card text</p></article>`, `/* Add the two rules */`), editableFiles: ["css"], tests: [test("css", "Styles paragraphs", "p\\s*\\{[\\s\\S]*line-height\\s*:"), test("css", "Styles the card class", "\\.card\\s*\\{[\\s\\S]*padding\\s*:[\\s\\S]*border\\s*:")], hints: ["Use p as the first selector.", "A class selector begins with a full stop.", "Write p with line-height, then .card with padding and border."], question: q("When is a class selector useful?", "When several elements share one component style", "When saving browser data", "When submitting a form", "Classes provide reusable styling hooks.") },
    { id: "box-model", title: "Control space with the box model", language: "CSS", objective: "Distinguish content, padding, border and margin.", concept: "Every visible element occupies a box. Padding creates inner breathing room, border surrounds it and margin separates it from neighbouring boxes.", method: "Add one kind of space at a time and inspect where it appears. Use box-sizing:border-box so declared widths include padding and borders.", keyTerms: ["box model", "padding", "margin"], exampleCode: `* { box-sizing: border-box; }\n.card { padding: 1rem; border: 2px solid #111936; margin-bottom: 1rem; }`, task: "Apply border-box sizing, then give .panel inner spacing, a border and outside spacing.", starterFiles: files(`<section class="panel">Readable content</section>`, `/* Add the box model rules */`), editableFiles: ["css"], tests: [test("css", "Uses border-box", "box-sizing\\s*:\\s*border-box"), test("css", "Panel has padding", "\\.panel\\s*\\{[\\s\\S]*padding\\s*:"), test("css", "Panel has a border", "\\.panel\\s*\\{[\\s\\S]*border\\s*:"), test("css", "Panel has margin", "\\.panel\\s*\\{[\\s\\S]*margin")], hints: ["Begin with a universal selector for box-sizing.", "Padding belongs inside the panel border.", "Add margin after the border to separate the panel from other content."], question: q("Where does padding create space?", "Between content and border", "Outside the browser", "Inside a JavaScript array", "Padding is inner space in the box model.") },
    { id: "tokens", title: "Name repeated design values", language: "CSS", objective: "Create and reuse CSS custom properties.", concept: "CSS custom properties give repeated values meaningful names. They reduce inconsistent copies and make the reason for a value clearer than a scattered hexadecimal code or number.", method: "Define stable project values in :root, then use var() wherever that decision applies. Name the purpose, such as --text, instead of a temporary appearance.", keyTerms: ["CSS custom property", ":root", "var"], exampleCode: `:root { --text: #111936; --accent: #5a2676; --space: 1rem; }\n.card { color: var(--text); padding: var(--space); }`, task: "Define text, accent and space properties, then use all three in the card rule.", starterFiles: files(`<article class="card">Project card</article>`, `/* Define and use the design values */`), editableFiles: ["css"], tests: [test("css", "Defines three properties", ":root\\s*\\{(?:[\\s\\S]*--[a-z-]+\\s*:){3}"), test("css", "Uses text property", "var\\(\\s*--text\\s*\\)"), test("css", "Uses accent property", "var\\(\\s*--accent\\s*\\)"), test("css", "Uses space property", "var\\(\\s*--space\\s*\\)")], hints: ["Create :root before the component rule.", "Every custom property name begins with two hyphens.", "Use color:var(--text), border-color:var(--accent) and padding:var(--space)."], question: q("What is the benefit of a named design value?", "It can be reused consistently and changed in one place", "It creates HTML content", "It sends a network request", "Custom properties centralise repeated design decisions.") },
    { id: "states", title: "Style interactive states", language: "CSS", objective: "Make hover and keyboard focus states visible.", concept: "Interactive controls need visible states so visitors can tell what is available and where keyboard focus is located. Focus must never rely only on a subtle colour change.", method: "Keep the base control readable, then add a clear focus-visible outline with enough contrast and space from the element.", keyTerms: ["interactive state", "focus-visible", "outline"], exampleCode: `button:hover { background: #37134d; }\nbutton:focus-visible { outline: 3px solid #ee9d2b; outline-offset: 3px; }`, task: "Add a hover treatment and a strong focus-visible outline to the button and links.", starterFiles: files(`<a href="#main">Skip to main</a><button>Save</button>`, `button, a { color: #111936; }\n/* Add states */`), editableFiles: ["css"], tests: [test("css", "Has a button hover state", "button:hover\\s*\\{"), test("css", "Has focus-visible", ":focus-visible\\s*\\{"), test("css", "Uses an outline", "outline\\s*:"), test("css", "Offsets the outline", "outline-offset\\s*:")], hints: ["Write the hover rule separately from focus.", "Group button:focus-visible and a:focus-visible if they share a rule.", "Use a 3px solid outline and a positive outline-offset."], question: q("Why is a focus indicator necessary?", "It shows keyboard users which control is active", "It stores a form value", "It changes HTML meaning", "Visible focus supports keyboard navigation.") },
  ];
  return { id: "css-system", title: "A consistent CSS system", description: "Control type, space, components and interaction states with reusable rules.", outcome: "A readable visual system that remains easy to change.", lessons: items.map((item) => lesson(item, audience)) as StageSpec["lessons"], project: projectLesson(3, audience, advanced), quizQuestion: q("Which selector is most reusable for a card component?", ".card", "article:first-child div", "#one-card-only", "A class gives repeated components a stable styling hook.") };
}

function stageFour(audience: string, advanced: boolean): StageSpec {
  const items: Array<LessonInput> = [
    { id: "viewport", title: "Start with the available width", language: "CSS", objective: "Build a narrow-screen base without horizontal scrolling.", concept: "Mobile-first CSS begins with the smallest useful layout as the default. Larger-screen changes are enhancements, so essential content remains readable if no media query applies.", method: "Use relative sizes, allow content to wrap and avoid fixed widths wider than the viewport. Test at 320 pixels before adding columns.", keyTerms: ["mobile first", "viewport", "overflow"], exampleCode: `.page { width: min(100% - 2rem, 70rem); margin-inline: auto; }\nimg { max-width: 100%; height: auto; }`, task: "Give .page a fluid maximum width and make the image shrink within its container.", starterFiles: files(`<main class="page"><img src="photo.jpg" alt="Workshop"><p>Useful details.</p></main>`, `/* Make the content fluid */`), editableFiles: ["css"], tests: [test("css", "Page uses a fluid width", "\\.page\\s*\\{[\\s\\S]*width\\s*:[^;]*(?:%|min\\()"), test("css", "Page has a maximum", "(?:max-width\\s*:|width\\s*:\\s*min\\()"), test("css", "Image cannot overflow", "img\\s*\\{[\\s\\S]*max-width\\s*:\\s*100%")], hints: ["Keep the page width tied to the viewport.", "Use either max-width with width or the min() function.", "Set img max-width to 100% and height to auto."], question: q("What does mobile first mean?", "The narrow layout is the default before wider enhancements", "Only phones may open the site", "All text must be small", "A mobile-first base protects essential content.") },
    { id: "flex", title: "Arrange one-dimensional content", language: "CSS", objective: "Use Flexbox for navigation that can wrap.", concept: "Flexbox arranges items mainly along one direction. It suits navigation and control rows where items need consistent gaps, alignment and permission to wrap.", method: "Turn the parent into a flex container, choose the gap and allow wrapping before adding alignment rules.", keyTerms: ["Flexbox", "flex container", "flex-wrap"], exampleCode: `nav { display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; }`, task: "Make nav a wrapping flex row with a 1rem gap and centred alignment.", starterFiles: files(`<nav><a href="#one">One</a><a href="#two">Two</a><a href="#three">Three</a></nav>`, `/* Arrange the links */`), editableFiles: ["css"], tests: [test("css", "Navigation uses Flexbox", "nav\\s*\\{[\\s\\S]*display\\s*:\\s*flex"), test("css", "Navigation wraps", "flex-wrap\\s*:\\s*wrap"), test("css", "Navigation has a gap", "gap\\s*:\\s*1rem"), test("css", "Navigation aligns items", "align-items\\s*:\\s*center")], hints: ["Style the nav parent, not each link first.", "Use display:flex and flex-wrap:wrap.", "Add gap:1rem and align-items:center to the same rule."], question: q("When is Flexbox a good choice?", "For a row or column whose items need alignment and gaps", "For storing JavaScript objects", "For adding image descriptions", "Flexbox is designed for one-dimensional layout.") },
    { id: "grid", title: advanced ? "Create self-fitting Grid tracks" : "Create a flexible card grid", language: "CSS", objective: advanced ? "Use repeat, auto-fit and minmax for responsive tracks." : "Use Grid with flexible columns and gaps.", concept: "CSS Grid controls rows and columns. Flexible tracks share available space and can collapse to one column without assigning a fixed width to every card.", method: advanced ? "Use repeat(auto-fit, minmax()) so the browser creates as many usable tracks as fit the container." : "Start with one track, then use repeat and fr units for wider layouts.", keyTerms: ["CSS Grid", "grid track", "minmax"], exampleCode: advanced ? `.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: 1rem; }` : `.cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }`, task: advanced ? "Create self-fitting card columns with a 15rem minimum and a 1rem gap." : "Create two equal flexible card columns with a 1rem gap.", starterFiles: files(`<section class="cards"><article>A</article><article>B</article><article>C</article></section>`, `.cards {\n  /* Add Grid */\n}`), editableFiles: ["css"], tests: [test("css", "Cards use Grid", "\\.cards\\s*\\{[\\s\\S]*display\\s*:\\s*grid"), test("css", "Uses repeat", "grid-template-columns\\s*:\\s*repeat\\("), test("css", "Uses flexible tracks", "(?:minmax\\(|1fr)"), test("css", "Has a gap", "gap\\s*:\\s*1rem")], hints: ["Begin with display:grid on .cards.", advanced ? "Use repeat(auto-fit, minmax(...))." : "Use repeat(2, minmax(0, 1fr)).", "Add gap:1rem after the track definition."], question: q("What does 1fr represent?", "One share of available Grid space", "One fixed pixel", "One form record", "The fr unit distributes available space between tracks.") },
    { id: "media", title: "Add a meaningful breakpoint", language: "CSS", objective: "Change layout when the content needs more room.", concept: "A media query applies rules only when its condition matches. A useful breakpoint comes from the layout becoming cramped, not from guessing a particular device model.", method: "Resize until the design needs to change, note that width and keep the media query focused on the rules that actually differ.", keyTerms: ["media query", "breakpoint", "responsive design"], exampleCode: `@media (min-width: 700px) {\n  .layout { grid-template-columns: 2fr 1fr; }\n}`, task: "Keep .layout one column by default and change it to a two-column 2fr 1fr layout from 700px.", starterFiles: files(`<main class="layout"><section>Main</section><aside>Related</aside></main>`, `.layout { display: grid; grid-template-columns: 1fr; gap: 1rem; }\n/* Add the wider layout */`), editableFiles: ["css"], tests: [test("css", "Base is one column", "\\.layout\\s*\\{[\\s\\S]*grid-template-columns\\s*:\\s*1fr"), test("css", "Uses a 700px breakpoint", "@media\\s*\\(min-width\\s*:\\s*700px\\)"), test("css", "Wider layout has two tracks", "@media[\\s\\S]*grid-template-columns\\s*:\\s*2fr\\s+1fr")], hints: ["Leave the existing base rule unchanged.", "Add @media (min-width:700px) after it.", "Inside the media query, set .layout grid-template-columns:2fr 1fr."], question: q("How should a breakpoint be chosen?", "Where the content and layout need to adapt", "From the learner's age", "At every possible pixel", "Content needs should determine responsive changes.") },
  ];
  return { id: "responsive", title: "Responsive layouts", description: "Build from a phone-sized base to flexible wider layouts.", outcome: "A project that remains readable without horizontal scrolling.", lessons: items.map((item) => lesson(item, audience)) as StageSpec["lessons"], project: projectLesson(4, audience, advanced), quizQuestion: q("What should remain consistent across screen sizes?", "The content meaning and available actions", "The exact number of columns", "A fixed page width", "Responsive design changes arrangement without removing the purpose.") };
}

function stageFive(audience: string, advanced: boolean): StageSpec {
  const simple: Array<LessonInput> = [
    { id: "values", title: "Store values with const and let", language: "JavaScript", objective: "Choose const for stable bindings and let for reassignment.", concept: "Variables give values useful names. Const prevents reassignment of the binding, while let communicates that the stored value is expected to change.", method: "Use const by default, switch to let only when the same name must receive a new value and choose names that describe the information.", keyTerms: ["const", "let", "assignment"], exampleCode: `const courseName = "Web foundations";\nlet completedLessons = 2;\ncompletedLessons = completedLessons + 1;`, task: "Create a stable projectName and a changing visitCount, then increase visitCount by one.", starterFiles: files(`<p id="output"></p>`, ``, `// Create the two values`), editableFiles: ["javascript"], tests: [test("javascript", "Uses const for projectName", "const\\s+projectName\\s*="), test("javascript", "Uses let for visitCount", "let\\s+visitCount\\s*="), test("javascript", "Updates visitCount", "visitCount\\s*=\\s*visitCount\\s*\\+\\s*1")], hints: ["ProjectName does not need reassignment, so use const.", "VisitCount changes, so use let.", "Assign visitCount + 1 back to visitCount."], question: q("When should let be used?", "When the same binding needs a new value", "For every string", "Only inside HTML", "Let signals intentional reassignment.") },
    { id: "functions", title: "Write a focused function", language: "JavaScript", objective: "Use parameters and return to transform a value.", concept: "A function gives one job a name. Parameters receive input and return sends a result back without forcing the function to change unrelated page state.", method: "State the function's job as one sentence, choose the smallest inputs it needs and return one predictable result.", keyTerms: ["function", "parameter", "return"], exampleCode: `function makeGreeting(name) {\n  return "Welcome, " + name;\n}\nconst message = makeGreeting("Amani");`, task: "Write formatTitle(text) so it returns Project: followed by the provided text, then call it.", starterFiles: files(`<p id="output"></p>`, ``, `// Define and call formatTitle`), editableFiles: ["javascript"], tests: [test("javascript", "Defines formatTitle", "function\\s+formatTitle\\s*\\(\\s*text\\s*\\)"), test("javascript", "Returns a result", "return\\s+[\"']Project:[^;]*\\+\\s*text"), test("javascript", "Calls the function", "formatTitle\\s*\\(")], hints: ["Give the function one parameter named text.", "Use return inside the braces.", "Return Project: plus text, then store or display formatTitle with a test value."], question: q("What does return do?", "Sends a function result back to its caller", "Creates a CSS selector", "Submits every form", "Return makes a computed result available outside the function.") },
    { id: "conditions", title: "Choose an outcome", language: "JavaScript", objective: "Use a condition for two clear outcomes.", concept: "A condition evaluates to true or false. If runs one block when true and else provides the alternative when the condition is false.", method: "Write the comparison in ordinary language first, then test a value on each side of the boundary.", keyTerms: ["condition", "boolean", "else"], exampleCode: `if (places > 0) {\n  message = "Places available";\n} else {\n  message = "Join the waiting list";\n}`, task: "Set accessMessage to Open when age is 13 or higher, otherwise set it to Ask a guardian.", starterFiles: files(`<p id="message"></p>`, ``, `const age = 14;\nlet accessMessage = "";\n// Add the decision`), editableFiles: ["javascript"], tests: [test("javascript", "Checks the age boundary", "if\\s*\\(\\s*age\\s*>=\\s*13"), test("javascript", "Sets the open outcome", "accessMessage\\s*=\\s*[\"']Open[\"']"), test("javascript", "Has the alternative", "else\\s*\\{[\\s\\S]*accessMessage\\s*=\\s*[\"']Ask a guardian[\"']")], hints: ["The comparison is age >= 13.", "Assign the first message inside if.", "Add else and assign the second message inside it."], question: q("When does else run?", "When the if condition is false", "Whenever CSS loads", "Before the condition is checked", "Else handles the alternative outcome.") },
    { id: "dom-output", title: "Show a result on the page", language: "JavaScript", objective: "Select an element and update its text safely.", concept: "The DOM is the browser's object model of the page. QuerySelector finds an element with a CSS selector and textContent changes only its plain text.", method: "Select once, check the selector matches the HTML and update textContent after calculating the result.", keyTerms: ["DOM", "querySelector", "textContent"], exampleCode: `const output = document.querySelector("#output");\noutput.textContent = "Three topics ready";`, task: "Select #result, store it as resultText and change its text to Project ready.", starterFiles: files(`<p id="result">Waiting</p>`, ``, `// Select and update the result`), editableFiles: ["javascript"], tests: [test("javascript", "Selects result", "(?:const|let)\\s+resultText\\s*=\\s*document\\.querySelector\\(\\s*[\"']#result[\"']"), test("javascript", "Updates the text", "resultText\\.textContent\\s*=\\s*[\"']Project ready[\"']")], hints: ["Create const resultText first.", "Pass #result to querySelector.", "On the next line assign Project ready to resultText.textContent."], question: q("Why use textContent for ordinary output?", "It treats the value as text instead of markup", "It permanently stores the value", "It changes CSS specificity", "TextContent is the safe choice for plain text output.") },
  ];
  const advancedItems: Array<LessonInput> = [
    { ...simple[1], id: "pure-functions", title: "Write a predictable pure function", objective: "Return a result without changing outside state.", concept: "A pure function uses only its inputs and returns the same result for the same inputs. It is easier to test because it does not secretly change the DOM or shared values.", task: "Write calculateTotal(price, quantity) so it returns the multiplication result, then test it with two input pairs.", starterFiles: files(`<p>Test the calculation in JavaScript.</p>`, ``, `// Define calculateTotal and two results`), tests: [test("javascript", "Defines calculateTotal", "function\\s+calculateTotal\\s*\\(\\s*price\\s*,\\s*quantity\\s*\\)"), test("javascript", "Returns multiplication", "return\\s+price\\s*\\*\\s*quantity"), test("javascript", "Calls it twice", "(?:calculateTotal\\s*\\([^)]*\\)[\\s\\S]*){2}")], question: q("Why is a pure function easier to test?", "Its result depends only on explicit inputs", "It always changes the page", "It hides its parameters", "Predictable inputs and outputs isolate the logic.") },
    { id: "objects", title: "Model one record with an object", language: "JavaScript", objective: "Store related named properties together.", concept: "An object represents one record with named properties. Stable property names let other functions read the same shape without depending on array positions.", method: "Choose property names from the information the application actually needs and give every similar record the same shape.", keyTerms: ["object", "property", "data model"], exampleCode: `const opportunity = { id: 1, title: "Workshop", category: "Learning", places: 12 };`, task: "Create a record object with id, title, category and available properties, then read its title.", starterFiles: files(`<p>Model the record.</p>`, ``, `// Create one record and read its title`), editableFiles: ["javascript"], tests: [test("javascript", "Creates a record object", "(?:const|let)\\s+record\\s*=\\s*\\{"), test("javascript", "Has an id", "id\\s*:"), test("javascript", "Has a title", "title\\s*:"), test("javascript", "Has a category", "category\\s*:"), test("javascript", "Reads the title", "record\\.title")], hints: ["Begin with const record = { }.", "Separate four name:value pairs with commas.", "After the object, create another const equal to record.title."], question: q("Why use an object for one record?", "Named properties describe related values clearly", "It makes all data anonymous", "It replaces responsive CSS", "Objects model related information with stable names.") },
    { id: "filter", title: "Derive a filtered collection", language: "JavaScript", objective: "Use filter without changing the source array.", concept: "Filter tests every array item and returns a new array containing only items that pass. Keeping the original array unchanged provides a reliable source of truth.", method: "Write a callback that returns one clear boolean condition, then test a matching and non-matching case.", keyTerms: ["filter", "callback", "source of truth"], exampleCode: `const available = records.filter(function (record) {\n  return record.available === true;\n});`, task: "Create availableRecords by filtering records where available is true.", starterFiles: files(`<p>Filter the records.</p>`, ``, `const records = [{ title: "A", available: true }, { title: "B", available: false }];\n// Create availableRecords`), editableFiles: ["javascript"], tests: [test("javascript", "Calls filter", "records\\.filter\\s*\\("), test("javascript", "Checks available", "record\\.available\\s*===\\s*true"), test("javascript", "Stores the result", "(?:const|let)\\s+availableRecords\\s*=")], hints: ["Call filter on records.", "Name the current item record.", "Return record.available === true and store the returned array as availableRecords."], question: q("What does filter return?", "A new array of items that pass the test", "One changed object", "A CSS rule", "Filter derives a new collection without mutating the source.") },
    { id: "sort", title: "Sort a copied collection", language: "JavaScript", objective: "Order data without mutating the source array.", concept: "Sort changes the array it runs on. Copying first protects the source of truth and makes the data flow easier to reason about.", method: "Create a shallow copy with spread syntax, then sort the copy with a comparison function and confirm the original order remains unchanged.", keyTerms: ["sort", "spread syntax", "mutation"], exampleCode: `const sorted = [...records].sort(function (a, b) {\n  return a.title.localeCompare(b.title);\n});`, task: "Copy records into sortedRecords and sort the copy by title.", starterFiles: files(`<p>Sort a copy.</p>`, ``, `const records = [{ title: "Zebra" }, { title: "Archive" }];\n// Copy and sort`), editableFiles: ["javascript"], tests: [test("javascript", "Copies with spread syntax", "\\[\\s*\\.\\.\\.records\\s*\\]"), test("javascript", "Calls sort", "\\.sort\\s*\\("), test("javascript", "Compares titles", "\\.title\\.localeCompare\\s*\\("), test("javascript", "Stores sortedRecords", "(?:const|let)\\s+sortedRecords\\s*=")], hints: ["Start sortedRecords with a copy of records.", "Call sort on the copied array.", "Return a.title.localeCompare(b.title) from the comparison function."], question: q("Why copy before sort?", "Sort mutates the array it receives", "Copying sends a network request", "CSS requires it", "Copying protects the source collection from accidental reordering.") },
  ];
  const chosen = advanced ? advancedItems : simple;
  return { id: "javascript", title: advanced ? "Application logic" : "JavaScript decisions", description: advanced ? "Write predictable functions and transform structured records." : "Store values, organise instructions and make clear decisions.", outcome: advanced ? "A tested logic layer for the project." : "JavaScript that calculates and shows useful results.", lessons: chosen.map((item) => lesson(item, audience)) as StageSpec["lessons"], project: projectLesson(5, audience, advanced), quizQuestion: advanced ? q("What should a pure function depend on?", "Its explicit inputs", "Hidden DOM state", "A CSS media query", "Explicit inputs make a function predictable.") : q("What should happen before changing DOM text?", "Calculate or choose the result", "Delete the HTML", "Add random code", "Keeping logic clear makes output easier to test.") };
}

function stageSix(audience: string, advanced: boolean): StageSpec {
  const items: Array<LessonInput> = advanced ? [
    { id: "state", title: "Define one source of application state", language: "JavaScript", objective: "Keep current records and filters in one state object.", concept: "Application state is the current information the interface represents. One source of truth prevents different parts of the page from disagreeing.", method: "Store the smallest necessary values, update state deliberately and call render after each successful change.", keyTerms: ["application state", "source of truth", "render"], exampleCode: `const state = { records: [], query: "" };\nfunction render() { /* read state and update the page */ }`, task: "Create state with records and query properties, then define a render function that reads both.", starterFiles: files(`<p id="summary"></p>`, ``, `// Define state and render`), editableFiles: ["javascript"], tests: [test("javascript", "Creates state", "const\\s+state\\s*=\\s*\\{"), test("javascript", "Stores records", "records\\s*:"), test("javascript", "Stores query", "query\\s*:"), test("javascript", "Defines render", "function\\s+render\\s*\\("), test("javascript", "Reads state", "state\\.(?:records|query)")], hints: ["Begin with one const object named state.", "Add records as an array and query as text.", "Define render below it and read state.records and state.query inside."], question: q("Why keep one source of truth?", "The interface can be rebuilt from one consistent state", "It makes values impossible to change", "It replaces all tests", "Central state reduces conflicting copies of information.") },
    { id: "create", title: "Add a record without mutating the array", language: "JavaScript", objective: "Use spread syntax to create an updated collection.", concept: "An immutable update creates a new array instead of changing the existing one in place. This makes before-and-after state easier to compare and debug.", method: "Validate the new record, then assign a new array that contains the previous records and the new record.", keyTerms: ["immutable update", "spread syntax", "record"], exampleCode: `state.records = [...state.records, newRecord];`, task: "Write addRecord(newRecord) so it validates the title, adds a new array value and returns true or false.", starterFiles: files(`<p>Add a record.</p>`, ``, `const state = { records: [] };\n// Define addRecord`), editableFiles: ["javascript"], tests: [test("javascript", "Defines addRecord", "function\\s+addRecord\\s*\\(\\s*newRecord\\s*\\)"), test("javascript", "Validates title", "newRecord\\.title"), test("javascript", "Creates a new array", "\\[\\s*\\.\\.\\.state\\.records\\s*,\\s*newRecord\\s*\\]"), test("javascript", "Returns a result", "return\\s+(?:true|false)")], hints: ["Check newRecord.title before updating state.", "Assign a new spread array to state.records.", "Return false for an invalid title and true after the update."], question: q("What is an immutable array update?", "Creating a new array with the required change", "Deleting every old item", "Changing CSS variables", "A new value makes state changes easier to trace.") },
    { id: "update", title: "Update a record by stable id", language: "JavaScript", objective: "Use map to replace one matching record.", concept: "A stable id identifies the same record even when its position changes. Map can return an updated copy for the match and the original object for every other record.", method: "Compare each id, use object spread for the matching update and return unchanged records from the other branch.", keyTerms: ["stable id", "map", "object spread"], exampleCode: `state.records = state.records.map(function (record) {\n  return record.id === id ? { ...record, title: title } : record;\n});`, task: "Write renameRecord(id, title) using map and object spread.", starterFiles: files(`<p>Update by id.</p>`, ``, `const state = { records: [{ id: 1, title: "Old" }] };\n// Define renameRecord`), editableFiles: ["javascript"], tests: [test("javascript", "Defines renameRecord", "function\\s+renameRecord\\s*\\(\\s*id\\s*,\\s*title\\s*\\)"), test("javascript", "Uses map", "state\\.records\\.map\\s*\\("), test("javascript", "Compares ids", "record\\.id\\s*===\\s*id"), test("javascript", "Uses object spread", "\\{\\s*\\.\\.\\.record\\s*,")], hints: ["Map over state.records.", "Compare record.id with the id parameter.", "Return a spread copy with title for the match, otherwise return record."], question: q("Why update by id instead of array position?", "The record remains identifiable after sorting or filtering", "Ids change every render", "Positions are always private", "Stable identity survives collection reordering.") },
    { id: "delete", title: "Remove a record predictably", language: "JavaScript", objective: "Use filter to derive a collection without one id.", concept: "Deleting from state can mean deriving a new array containing every record except the selected id. The original record positions do not matter.", method: "Filter with a not-equal comparison and test both an existing id and an unknown id.", keyTerms: ["CRUD", "delete", "filter"], exampleCode: `state.records = state.records.filter(function (record) { return record.id !== id; });`, task: "Write deleteRecord(id) with filter and return the remaining record count.", starterFiles: files(`<p>Delete by id.</p>`, ``, `const state = { records: [{ id: 1 }, { id: 2 }] };\n// Define deleteRecord`), editableFiles: ["javascript"], tests: [test("javascript", "Defines deleteRecord", "function\\s+deleteRecord\\s*\\(\\s*id\\s*\\)"), test("javascript", "Uses filter", "state\\.records\\.filter\\s*\\("), test("javascript", "Excludes the id", "record\\.id\\s*!==\\s*id"), test("javascript", "Returns length", "return\\s+state\\.records\\.length")], hints: ["Filter state.records inside the function.", "Keep records whose id is not the selected id.", "Assign the filtered array back, then return state.records.length."], question: q("Which CRUD action removes a record?", "Delete", "Read", "Create CSS", "CRUD names create, read, update and delete operations.") },
  ] : [
    { id: "arrays", title: "Store a collection in an array", language: "JavaScript", objective: "Create an ordered collection and read items by index.", concept: "An array stores related values in order. Indexes begin at zero, and length reports how many items the array currently contains.", method: "Keep one kind of value in the collection, use square brackets and test the first, last and missing positions.", keyTerms: ["array", "index", "length"], exampleCode: `const topics = ["HTML", "CSS", "JavaScript"];\nconst first = topics[0];\nconst total = topics.length;`, task: "Create a three-item topics array, read the second item and store the total length.", starterFiles: files(`<p>Use a collection.</p>`, ``, `// Create topics, chosenTopic and totalTopics`), editableFiles: ["javascript"], tests: [test("javascript", "Creates three topics", "(?:const|let)\\s+topics\\s*=\\s*\\[[^\\]]+,[^\\]]+,[^\\]]+\\]"), test("javascript", "Reads index 1", "topics\\s*\\[\\s*1\\s*\\]"), test("javascript", "Reads length", "topics\\.length")], hints: ["Use square brackets and commas.", "The second item is at index 1.", "Store topics[1], then store topics.length in another const."], question: q("What is the first array index?", "0", "1", "-1", "JavaScript array indexing begins at zero.") },
    { id: "objects", title: "Describe records with objects", language: "JavaScript", objective: "Store named properties for each item.", concept: "An object groups related values under property names. Consistent record shapes make the collection easier to display, filter and validate.", method: "Choose property names once and repeat the same names for every record of that kind.", keyTerms: ["object", "property", "record"], exampleCode: `const resource = { title: "HTML guide", category: "Web", minutes: 12 };`, task: "Create two resource objects that each have title, category and minutes properties.", starterFiles: files(`<p>Model two resources.</p>`, ``, `// Create resourceOne and resourceTwo`), editableFiles: ["javascript"], tests: [test("javascript", "Creates first object", "(?:const|let)\\s+resourceOne\\s*=\\s*\\{"), test("javascript", "Creates second object", "(?:const|let)\\s+resourceTwo\\s*=\\s*\\{"), test("javascript", "Uses title properties", "(?:title\\s*:){2}"), test("javascript", "Uses category properties", "(?:category\\s*:){2}")], hints: ["Begin each record with const and braces.", "Use the same property names in both.", "Give title and category text values and minutes a number value."], question: q("Why keep the same property names?", "The same code can process every record", "It changes the font", "It hides the data", "Consistent shapes make data predictable.") },
    { id: "foreach", title: "Process every record", language: "JavaScript", objective: "Use forEach for repeated work.", concept: "ForEach calls a function once for every array item. The callback parameter represents the current value during that iteration.", method: "Name the current item clearly and keep the repeated instruction focused on that one item.", keyTerms: ["forEach", "callback", "iteration"], exampleCode: `topics.forEach(function (topic) {\n  output = output + topic + " ";\n});`, task: "Loop through skills with forEach and add each value to the output string.", starterFiles: files(`<p id="result"></p>`, ``, `const skills = ["HTML", "CSS", "JavaScript"];\nlet output = "";\n// Add the loop`), editableFiles: ["javascript"], tests: [test("javascript", "Calls forEach", "skills\\.forEach\\s*\\("), test("javascript", "Names the current skill", "function\\s*\\(\\s*skill\\s*\\)"), test("javascript", "Adds each skill", "output\\s*(?:\\+=|=\\s*output\\s*\\+)")], hints: ["Call skills.forEach.", "Use a function parameter named skill.", "Inside the callback, add skill and a space to output."], question: q("How often does forEach run its callback?", "Once for every array item", "Only once for the whole page", "Only when CSS fails", "ForEach visits each item in order.") },
    { id: "render", title: "Render safe list items", language: "JavaScript", objective: "Create DOM elements from array records.", concept: "Rendering turns data into visible interface elements. CreateElement and textContent keep plain text separate from HTML markup and reduce accidental injection.", method: "Select the list once, create one li in each iteration, set its text and append it.", keyTerms: ["render", "createElement", "append"], exampleCode: `const item = document.createElement("li");\nitem.textContent = resource.title;\nlist.append(item);`, task: "Render every resource title as an li inside #resource-list.", starterFiles: files(`<ul id="resource-list"></ul>`, ``, `const resources = [{ title: "HTML" }, { title: "CSS" }];\nconst list = document.querySelector("#resource-list");\n// Render the titles`), editableFiles: ["javascript"], tests: [test("javascript", "Loops through resources", "resources\\.forEach\\s*\\("), test("javascript", "Creates li elements", "createElement\\(\\s*[\"']li[\"']"), test("javascript", "Uses title as text", "textContent\\s*=\\s*resource\\.title"), test("javascript", "Appends the item", "list\\.append(?:Child)?\\s*\\(")], hints: ["Start a forEach loop on resources.", "Create the li inside the callback.", "Set item.textContent from resource.title, then append item to list."], question: q("Why use textContent for record titles?", "It inserts plain text instead of interpreting markup", "It stores the record forever", "It creates a media query", "TextContent is appropriate for untrusted or ordinary text values.") },
  ];
  return { id: "data", title: advanced ? "Application state and CRUD" : "Structured data and rendering", description: advanced ? "Create, update and remove records through one predictable state model." : "Organise related information and generate consistent page content.", outcome: advanced ? "A state layer with traceable CRUD operations." : "A data-driven list rendered from JavaScript records.", lessons: items.map((item) => lesson(item, audience)) as StageSpec["lessons"], project: projectLesson(6, audience, advanced), quizQuestion: advanced ? q("What gives a record stable identity?", "A unique id", "Its current array position", "Its text colour", "A stable id survives filtering and sorting.") : q("What separates data from presentation?", "Records store values while a render function builds the interface", "CSS stores all records", "HTML performs every calculation", "Separating concerns reduces repeated markup and logic.") };
}

function stageSeven(audience: string, advanced: boolean): StageSpec {
  const standard: Array<LessonInput> = [
    { id: "select", title: "Select the elements you need", language: "JavaScript", objective: "Store reliable DOM references before adding behaviour.", concept: "QuerySelector uses a CSS selector to find the first matching element. A precise id selector is useful when one control has one unique job.", method: "Confirm the selector exists in HTML, store it in a clearly named const and avoid selecting the same element repeatedly.", keyTerms: ["DOM", "querySelector", "element reference"], exampleCode: `const form = document.querySelector("#search-form");\nconst input = document.querySelector("#search-input");`, task: "Select #filter-form, #filter-input and #result, then store each in a descriptive const.", starterFiles: files(`<form id="filter-form"><input id="filter-input"><button>Filter</button></form><p id="result"></p>`, ``, `// Select the three elements`), editableFiles: ["javascript"], tests: [test("javascript", "Selects the form", "querySelector\\(\\s*[\"']#filter-form[\"']"), test("javascript", "Selects the input", "querySelector\\(\\s*[\"']#filter-input[\"']"), test("javascript", "Selects the result", "querySelector\\(\\s*[\"']#result[\"']")], hints: ["Use one const for each element.", "Every selector begins with # because the HTML uses ids.", "Name them form, input and result, then call document.querySelector for each id."], question: q("What does querySelector receive?", "A CSS selector", "A password", "A database row", "QuerySelector locates an element using selector syntax.") },
    { id: "events", title: "Respond to a user event", language: "JavaScript", objective: "Run a function after a click or submission.", concept: "An event listener waits for a named browser event and calls a function when it occurs. The listener should be attached to the element responsible for that action.", method: "Choose the semantic event, add one listener and test both mouse and keyboard activation where applicable.", keyTerms: ["event", "event listener", "submit"], exampleCode: `form.addEventListener("submit", function (event) {\n  event.preventDefault();\n});`, task: "Add a submit listener to form and prevent the normal page reload.", starterFiles: files(`<form id="form"><input><button>Send</button></form>`, ``, `const form = document.querySelector("#form");\n// Listen for submission`), editableFiles: ["javascript"], tests: [test("javascript", "Listens for submit", "form\\.addEventListener\\s*\\(\\s*[\"']submit[\"']"), test("javascript", "Receives the event", "function\\s*\\(\\s*event\\s*\\)"), test("javascript", "Prevents reload", "event\\.preventDefault\\s*\\(")], hints: ["Call addEventListener on form.", "The event name is submit.", "Give the callback an event parameter and call event.preventDefault inside."], question: q("Why handle submit instead of button click?", "It also works when the form is submitted from the keyboard", "It removes labels", "It stores CSS", "The submit event represents the complete form action.") },
    { id: "validation", title: "Validate before accepting input", language: "JavaScript", objective: "Reject an empty value and provide clear feedback.", concept: "Client-side validation protects the quality of an interaction, not secret data. Trim removes surrounding whitespace so a value containing only spaces is still treated as empty.", method: "Read and trim the value, test the invalid case first and show a specific action the visitor can take.", keyTerms: ["validation", "trim", "error message"], exampleCode: `const value = input.value.trim();\nif (value === "") { result.textContent = "Enter a topic first"; }`, task: "Trim the input value, show Enter a topic when empty and show Saved when it has text.", starterFiles: files(`<input id="topic"><p id="result" role="status"></p>`, ``, `const input = document.querySelector("#topic");\nconst result = document.querySelector("#result");\n// Validate the value`), editableFiles: ["javascript"], tests: [test("javascript", "Trims the value", "input\\.value\\.trim\\s*\\("), test("javascript", "Checks empty text", "(?:===|==)\\s*[\"'][\"']"), test("javascript", "Shows empty feedback", "textContent\\s*=\\s*[\"']Enter a topic[\"']"), test("javascript", "Shows success feedback", "textContent\\s*=\\s*[\"']Saved[\"']")], hints: ["Store input.value.trim() in a const.", "Compare the value with an empty string.", "Use if for Enter a topic and else for Saved."], question: q("Why call trim before an empty check?", "Spaces alone should not count as useful input", "It changes HTML tags", "It downloads the value", "Trim removes surrounding whitespace before validation.") },
    { id: "storage", title: "Save and restore a preference", language: "JavaScript", objective: "Use localStorage for a small non-sensitive value.", concept: "LocalStorage stores text under a key in the browser. GetItem can return null on a first visit, so code needs a safe default before displaying the value.", method: "Use a project-specific key, save only when validation passes and test both a first visit and a returning visit.", keyTerms: ["localStorage", "setItem", "getItem"], exampleCode: `localStorage.setItem("kidycode-topic", value);\nconst saved = localStorage.getItem("kidycode-topic") || "No topic saved";`, task: "Save the chosen topic under project-topic, then restore it with a safe fallback and show it in #result.", starterFiles: files(`<p id="result"></p>`, ``, `const chosenTopic = "Web design";\nconst result = document.querySelector("#result");\n// Save and restore`), editableFiles: ["javascript"], tests: [test("javascript", "Saves the topic", "localStorage\\.setItem\\s*\\(\\s*[\"']project-topic[\"']"), test("javascript", "Restores the topic", "localStorage\\.getItem\\s*\\(\\s*[\"']project-topic[\"']"), test("javascript", "Uses a fallback", "(?:\\|\\||\\?\\?)"), test("javascript", "Displays the result", "result\\.textContent\\s*=")], hints: ["Call setItem with a key and value.", "Call getItem with the exact same key.", "Use || with fallback text, then assign the restored value to result.textContent."], question: q("What can getItem return when a key is missing?", "null", "A CSS rule", "A form element", "Missing browser-storage keys return null.") },
  ];
  const advancedItems: Array<LessonInput> = [
    { id: "fetch", title: "Request JSON with fetch", language: "JavaScript", objective: "Make an asynchronous request and read a JSON response.", concept: "Fetch returns a Promise for an HTTP response. The response status must be checked before reading JSON because a completed network request can still contain an error status.", method: "Show a loading state, await the response, check response.ok and then await response.json inside a try block.", keyTerms: ["fetch", "Promise", "JSON"], exampleCode: `const response = await fetch(url);\nif (!response.ok) throw new Error("Request failed");\nconst data = await response.json();`, task: "Write async loadData that fetches the provided data URL, checks response.ok and returns response.json().", starterFiles: files(`<p id="status"></p>`, ``, `const url = "data:application/json,%7B%22title%22%3A%22Ready%22%7D";\n// Define loadData`), editableFiles: ["javascript"], tests: [test("javascript", "Defines async loadData", "async\\s+function\\s+loadData\\s*\\("), test("javascript", "Awaits fetch", "await\\s+fetch\\s*\\("), test("javascript", "Checks response status", "response\\.ok"), test("javascript", "Reads JSON", "response\\.json\\s*\\(")], hints: ["Begin with async function loadData().", "Await fetch(url) and store the response.", "If response.ok is false throw an Error, otherwise return response.json()."], question: q("Why check response.ok?", "A network response can complete with an HTTP error status", "JSON always checks itself", "It creates the DOM", "Fetch only rejects automatically for network failures, not every HTTP error.") },
    { id: "loading", title: "Represent loading, success and empty states", language: "JavaScript", objective: "Give visible feedback during an asynchronous request.", concept: "An interface should show what is happening before, during and after a request. Loading, success and empty are different states and need distinct messages.", method: "Set loading before awaiting, inspect the returned data and choose the final message from evidence rather than leaving old text on screen.", keyTerms: ["loading state", "empty state", "status message"], exampleCode: `statusText.textContent = "Loading...";\nconst data = await loadData();\nstatusText.textContent = data.length ? "Ready" : "No results";`, task: "Set Loading before awaiting loadData, then show Ready when results exist or No results when empty.", starterFiles: files(`<p id="status" role="status">Waiting</p>`, ``, `const statusText = document.querySelector("#status");\nasync function showResults() {\n  // Add states\n}`), editableFiles: ["javascript"], tests: [test("javascript", "Shows loading", "textContent\\s*=\\s*[\"']Loading\\.\\.\\.[\"']"), test("javascript", "Awaits data", "await\\s+loadData\\s*\\("), test("javascript", "Checks returned length", "\\.length"), test("javascript", "Shows empty state", "textContent\\s*=\\s*[\"']No results[\"']"), test("javascript", "Shows ready state", "textContent\\s*=\\s*[\"']Ready[\"']")], hints: ["Update status before the await line.", "Store the awaited result and inspect its length.", "Use if and else to assign Ready or No results after loading finishes."], question: q("When should the loading message appear?", "Before the awaited request starts", "Only after an error", "Inside CSS", "Immediate feedback tells the visitor the action was received.") },
    { id: "errors", title: "Handle a failed request", language: "JavaScript", objective: "Use try, catch and finally for reliable feedback.", concept: "Try contains work that may fail, catch receives the error and finally runs whether the operation succeeds or fails. Useful error messages state the next action without exposing private technical details.", method: "Catch at the point where the interface can recover, log only safe development details and restore controls in finally.", keyTerms: ["try", "catch", "finally"], exampleCode: `try { await loadData(); } catch (error) { statusText.textContent = "Could not load data. Try again."; } finally { button.disabled = false; }`, task: "Wrap await loadData in try and catch, show a retry message on failure and re-enable the button in finally.", starterFiles: files(`<button id="load">Load</button><p id="status"></p>`, ``, `const button = document.querySelector("#load");\nconst statusText = document.querySelector("#status");\nasync function run() {\n  button.disabled = true;\n  // Handle success and failure\n}`), editableFiles: ["javascript"], tests: [test("javascript", "Uses try", "try\\s*\\{"), test("javascript", "Uses catch", "catch\\s*\\("), test("javascript", "Shows retry feedback", "textContent\\s*=\\s*[\"'][^\"']*Try again[^\"']*[\"']"), test("javascript", "Uses finally", "finally\\s*\\{"), test("javascript", "Re-enables button", "button\\.disabled\\s*=\\s*false")], hints: ["Place await loadData inside try.", "Add catch with an error parameter and update status text.", "Add finally after catch and set button.disabled to false."], question: q("When does finally run?", "After success or failure", "Only when CSS loads", "Before try", "Finally is used for cleanup that must always happen.") },
    { id: "abort", title: "Ignore stale results", language: "JavaScript", objective: "Use a request identifier to prevent old data replacing newer data.", concept: "Asynchronous requests can finish in a different order from the order they started. A request id lets the interface ignore a stale response from an earlier action.", method: "Increment the id before each request, capture the current value and update the interface only if the captured value is still latest.", keyTerms: ["race condition", "stale result", "request id"], exampleCode: `let latestRequest = 0;\nasync function search() { const requestId = ++latestRequest; const data = await loadData(); if (requestId !== latestRequest) return; render(data); }`, task: "Add a latestRequest counter and return early when an older request finishes after a newer one.", starterFiles: files(`<p>Protect current results.</p>`, ``, `let latestRequest = 0;\nasync function search() {\n  // Track this request\n  const data = await loadData();\n  // Ignore stale data\n  render(data);\n}`), editableFiles: ["javascript"], tests: [test("javascript", "Increments request id", "\\+\\+latestRequest|latestRequest\\s*\\+\\s*1"), test("javascript", "Stores current id", "(?:const|let)\\s+requestId"), test("javascript", "Compares ids", "requestId\\s*!==\\s*latestRequest"), test("javascript", "Returns for stale data", "if\\s*\\([^)]*requestId[^)]*\\)[\\s\\S]*return")], hints: ["Create requestId from an incremented latestRequest.", "After await, compare requestId with latestRequest.", "If they differ, return before render(data)."], question: q("Why can a stale result appear?", "An older request can finish after a newer request", "HTML changes network order", "CSS removes data", "Asynchronous completion order is not guaranteed.") },
  ];
  const items = advanced ? advancedItems : standard;
  return { id: "interaction", title: advanced ? "External data and failure states" : "DOM, forms and browser storage", description: advanced ? "Request data, represent every state and recover from failure." : "Connect controls to validation, feedback and safe local state.", outcome: advanced ? "An interface with explicit loading, empty, success and error behaviour." : "A form interaction that restores one safe preference.", lessons: items.map((item) => lesson(item, audience)) as StageSpec["lessons"], project: projectLesson(7, audience, advanced), quizQuestion: advanced ? q("What makes an async interface trustworthy?", "It represents loading, empty, success and error states explicitly", "It hides all errors", "It assumes every request succeeds", "Every outcome needs clear visible feedback.") : q("What should happen before saving form input?", "Validate and explain any problem", "Remove the label", "Reload immediately", "Validation prevents unclear or empty stored values.") };
}

function stageEight(audience: string, advanced: boolean): StageSpec {
  const items: Array<LessonInput> = [
    { id: "debug", title: "Debug from evidence", language: "JavaScript", objective: "Reproduce a fault and isolate its cause.", concept: "Debugging is a controlled investigation. The expected result, actual result and smallest reproducible case provide more useful evidence than changing several lines at random.", method: "Reproduce the same failure, inspect one likely layer, change one cause and rerun the same test before declaring the repair complete.", keyTerms: ["debugging", "expected result", "runtime error"], exampleCode: `Expected: status says Ready\nActual: status stays Waiting\nCheck: selector is #stats but HTML id is status\nRepair: use #status\nRetest: pass`, task: "Repair the incorrect selector and missing function call, then write the expected and actual result in comments.", starterFiles: files(`<p id="status">Waiting</p>`, ``, `function showReady() { document.querySelector("#stats").textContent = "Ready"; }\n// Record evidence and run the function`), editableFiles: ["javascript"], tests: [test("javascript", "Uses the correct selector", "querySelector\\(\\s*[\"']#status[\"']"), test("javascript", "Calls showReady", "showReady\\s*\\(\\s*\\)"), test("javascript", "Records expected evidence", "Expected\\s*:"), test("javascript", "Records actual evidence", "Actual\\s*:")], hints: ["Compare the HTML id with the selector text.", "Fix only the selector before running again.", "Add Expected and Actual comments, then call showReady after the function."], question: q("Why change one cause before rerunning?", "It shows which change affected the result", "It makes the file longer", "It prevents testing", "Controlled changes produce useful evidence.") },
    { id: "accessibility", title: "Audit keyboard and text alternatives", language: "HTML", objective: "Repair common accessibility barriers.", concept: "An accessibility audit checks whether people can perceive, understand and operate the interface in different ways. Images, forms, focus order and status feedback need equivalent information.", method: "Navigate using only the keyboard, inspect labels and alternative text and verify changing messages are available without relying only on colour.", keyTerms: ["accessibility audit", "keyboard navigation", "alternative text"], exampleCode: `<img src="team.jpg" alt="Two people reviewing a website">\n<label for="search">Search</label><input id="search">\n<p role="status"></p>`, task: "Add useful alt text, connect the search label and add a status region.", starterFiles: files(`<img src="team.jpg">\n<label>Search</label><input id="search">\n<p id="result"></p>`), editableFiles: ["html"], tests: [test("html", "Image has alt text", "<img[^>]+alt=[\"'][^\"']{8,}[\"']"), test("html", "Label is connected", "<label[^>]+for=[\"']search[\"']"), test("html", "Result is a status region", "<p[^>]+role=[\"']status[\"']")], hints: ["Describe the useful image information.", "Add for=search to the label.", "Add role=status to the result paragraph."], question: q("What should an accessibility audit include?", "Keyboard use, labels, alternatives and feedback", "Only visual decoration", "Only file size", "Accessibility covers perception, operation and understanding.") },
    { id: "security", title: advanced ? "Treat external text as untrusted" : "Protect personal information", language: advanced ? "JavaScript" : "HTML", objective: advanced ? "Render external strings as text rather than executable markup." : "Write a safe project credit without identifying a child.", concept: advanced ? "Text from users or services is untrusted input. TextContent keeps it as text, while assigning it to innerHTML can interpret tags and scripts." : "A public project should demonstrate the work without publishing a full name, school, phone number, address or exact location.", method: advanced ? "Use textContent or created text nodes for ordinary values and validate data shape before rendering." : "Use a nickname and name the technologies used, then review the page for personal details before sharing.", keyTerms: advanced ? ["untrusted input", "textContent", "sanitization"] : ["privacy", "project note", "credit"], exampleCode: advanced ? `const item = document.createElement("li");\nitem.textContent = record.title;\nlist.append(item);` : `<footer><p>Built by SkyCoder using HTML, CSS and JavaScript.</p></footer>`, task: advanced ? "Replace the unsafe innerHTML assignment with createElement, textContent and append." : "Add a footer credit with a nickname and HTML, CSS and JavaScript, without personal details.", starterFiles: advanced ? files(`<ul id="list"></ul>`, ``, `const record = { title: "Community update" };\nconst list = document.querySelector("#list");\nlist.innerHTML = "<li>" + record.title + "</li>";`) : files(`<footer><!-- Add a safe credit --></footer>`), editableFiles: advanced ? ["javascript"] : ["html"], tests: advanced ? [test("javascript", "Creates an element", "createElement\\(\\s*[\"']li[\"']"), test("javascript", "Uses textContent", "textContent\\s*=\\s*record\\.title"), test("javascript", "Appends safely", "list\\.append(?:Child)?\\s*\\("), test("javascript", "Removes innerHTML", "^(?![\\s\\S]*innerHTML)[\\s\\S]*$")] : [test("html", "Uses a footer", "<footer[\\s>]"), test("html", "Mentions HTML", "HTML"), test("html", "Mentions CSS", "CSS"), test("html", "Mentions JavaScript", "JavaScript")], hints: advanced ? ["Create a new li instead of building an HTML string.", "Assign record.title to item.textContent.", "Append item to list and remove the innerHTML line."] : ["Begin with Built by and a nickname.", "Name the three technologies.", "Keep the complete credit inside footer and remove identifying details."], question: advanced ? q("Why prefer textContent for an external title?", "It keeps the value as plain text", "It automatically trusts the service", "It makes data permanent", "Plain-text rendering avoids interpreting unexpected markup.") : q("What should stay out of a public child project?", "School and exact location", "The technologies used", "A project title", "Identifying information should remain private.") },
    { id: "release", title: "Write a useful release note", language: "HTML", objective: "Document the project purpose, tested features and known limit.", concept: "A release note helps another person understand what the project does, which behaviours were tested and what remains outside the current version.", method: "Write concrete evidence rather than claiming the project is perfect. Name one tested flow and one honest limitation.", keyTerms: ["release note", "test case", "known limitation"], exampleCode: `<section id="release-notes"><h2>Version 1</h2><p>Tested: form validation and phone layout.</p><p>Known limit: data stays on this device.</p></section>`, task: "Add release notes with the project purpose, at least two tested features and one known limitation.", starterFiles: files(`<main><h1>{{TITLE}}</h1><!-- Add release notes --></main>`), editableFiles: ["html"], tests: [test("html", "Has release notes section", "id=[\"']release-notes[\"']"), test("html", "Names tested work", "Tested\\s*:"), test("html", "Names a limitation", "Known limit(?:ation)?\\s*:"), test("html", "Has a version heading", "<h2[\\s>][^<]*(?:Version|Release)[^<]*</h2>")], hints: ["Create a section with id=release-notes.", "Add a Version 1 heading and a Tested paragraph.", "Name two tested flows, then add a Known limitation paragraph."], question: q("Why record a known limitation?", "It sets an honest boundary for the current version", "It makes testing unnecessary", "It hides unfinished work", "Clear limitations help users and future developers make informed decisions.") },
  ];
  return { id: "quality", title: "Test, protect and release", description: "Use evidence to repair faults, improve access and explain the finished work.", outcome: "A tested project with a clear release note and safe sharing choices.", lessons: items.map((item) => lesson(item, audience)) as StageSpec["lessons"], project: projectLesson(8, audience, advanced), quizQuestion: q("What should happen after a repair?", "Rerun the same test and record the result", "Change several unrelated features", "Delete the expected result", "A consistent retest proves whether the repair worked.") };
}

function finalExam(advanced: boolean): CourseSpec["finalExam"] {
  return [
    q("What do semantic HTML elements communicate?", "The jobs of page regions", "A stored password", "A screen width", "Semantic names create a meaningful document outline."),
    q("How is a label connected to its input?", "Matching for and id values", "Matching font sizes", "A JavaScript loop", "The matching values create the connection."),
    q("Why use a CSS custom property?", "To reuse a named design value consistently", "To submit a form", "To create an object", "Custom properties centralise design decisions."),
    q("What is mobile-first CSS?", "A narrow base enhanced for wider space", "CSS used only on phones", "A fixed desktop width", "The default layout protects the smallest supported viewport."),
    advanced ? q("Why should a pure function depend on explicit inputs?", "Its result becomes predictable and testable", "It can hide DOM changes", "It removes return values", "Pure logic is easier to isolate and verify.") : q("What does return do in a function?", "Sends a result back to the caller", "Creates a CSS class", "Labels an input", "Return makes the function result available."),
    advanced ? q("Why use a stable record id?", "It identifies the record after sorting or filtering", "It changes on every render", "It controls text colour", "Stable identity is independent of array position.") : q("What does an array store?", "An ordered collection of values", "Only CSS declarations", "One HTML attribute", "Arrays group values that code can process."),
    q("Why use textContent for ordinary or external text?", "It treats the value as text rather than markup", "It stores data forever", "It performs a network request", "TextContent is safer for plain strings."),
    advanced ? q("Why check response.ok after fetch?", "HTTP error responses do not always reject fetch", "It parses CSS", "It creates the request URL", "The status must be checked explicitly.") : q("Which event represents a completed form action?", "submit", "hover", "resize text", "Submit covers button and keyboard form activation."),
    q("What belongs in browser storage?", "A small non-sensitive value needed by the interface", "A password", "A private identity document", "Device storage is not a place for secrets."),
    q("What proves a repair worked?", "The same test now produces the expected result", "The file became longer", "The page has more colours", "A controlled retest provides evidence."),
  ];
}

function practicalExam(advanced: boolean): CourseSpec["practicalExam"] {
  return advanced ? {
    title: "Repair an asynchronous resource loader",
    language: "HTML and JavaScript",
    brief: "Connect the status region, check the response and show a clear retry message in catch.",
    starterCode: `<p id="status"></p>\n<script>\nconst statusText = document.querySelector("#stats");\nasync function load() {\n  try {\n    const response = await fetch("data:application/json,%7B%22title%22%3A%22Ready%22%7D");\n    const data = await response.json();\n    statusText.textContent = data.title;\n  } catch (error) {\n    statusText.textContent = "";\n  }\n}\nload();\n</script>`,
    requiredPatterns: ["querySelector\\(\\s*[\"']#status[\"']", "response\\.ok", "catch[\\s\\S]*textContent\\s*=\\s*[\"'][^\"']*Try again"],
  } : {
    title: "Repair a form interaction",
    language: "HTML and JavaScript",
    brief: "Connect the label, prevent form reload and make the status say Saved after valid input.",
    starterCode: `<form id="save-form"><label>Topic</label><input id="topic"><button>Save</button></form><p id="status"></p>\n<script>\nconst form = document.querySelector("#save-form");\nform.addEventListener("submit", function (event) {\n  document.querySelector("#status").textContent = "";\n});\n</script>`,
    requiredPatterns: ["<label[^>]+for=[\"']topic[\"']", "event\\.preventDefault\\s*\\(", "textContent\\s*=\\s*[\"']Saved[\"']"],
  };
}

export function buildPathwayCourse(profile: PathProfile): CourseBundle {
  const spec: CourseSpec = {
    id: profile.id,
    title: profile.title,
    ageRange: profile.ageRange,
    ages: profile.ages,
    estimatedHours: profile.estimatedHours,
    passMark: 7,
    projectChoices: profile.projectChoices,
    stages: [stageOne(profile.audience, profile.advanced), stageTwo(profile.audience, profile.advanced), stageThree(profile.audience, profile.advanced), stageFour(profile.audience, profile.advanced), stageFive(profile.audience, profile.advanced), stageSix(profile.audience, profile.advanced), stageSeven(profile.audience, profile.advanced), stageEight(profile.audience, profile.advanced)],
    finalExam: finalExam(profile.advanced),
    practicalExam: practicalExam(profile.advanced),
  };
  return createCourse(spec);
}
